-- data_gap found during Part B: 50 gaps (28 conflict, 2 required, 20 extra).
-- Same pattern as 003: update existing rows by category (status is not touched), then insert missing ones as open.
WITH v (category, affected_entity, description, source_reference, notes) AS (
  VALUES
  ('old_prereq_conflict_csci_207', 'requisite', 'CSCI 207 prerequisite: the old course table (p.20) says CSCI 479; the course description (p.36) says CSCI 201. Omar chose the study-plan workbook instead: CSCI 207 requires only CSCI 112 (all 8 sheets); the track image agrees.', 'Old CS bylaw course tables, p.20; course descriptions, p.36; CS-StudyPlan_Sep 24.xlsx, sheet Science_Intensive_Media, E20; track images (team copy, not in source-files)', 'Resolved by team decision (BRIEF.md §6, 2026-11-27): CSCI 207 requires CSCI 112 (track image; all 8 sheets, E20). Current value: 009 requires CSCI 112 (group 1).'),
  ('old_prereq_conflict_csci_217', 'requisite', 'CSCI 217 prerequisite: the old course table (p.20) says CSCI 207; the course description (p.36) says CSCI 201. Omar kept the table reading.', 'Old CS bylaw course tables, p.20; course descriptions, p.36', 'Current value: 009 requires CSCI 207 (the table reading).'),
  ('old_prereq_conflict_csci_311', 'requisite', 'CSCI 311 prerequisite: the old course table (p.20) says CSCI 221; the course description (p.37) says CSCI 201. Omar kept the table reading.', 'Old CS bylaw course tables, p.20; course descriptions, p.37', 'Current value: 009 requires CSCI 221 (the table reading).'),
  ('old_prereq_conflict_csci_313', 'requisite', 'CSCI 313 prerequisite: the old course table (p.20) says CSCI 207; the course description (p.37) says CSCI 207 and CSCI 217. Omar kept the table reading.', 'Old CS bylaw course tables, p.20; course descriptions, p.37', 'Current value: 009 requires CSCI 207 (the table reading).'),
  ('old_prereq_conflict_csci_322', 'requisite', 'CSCI 322 prerequisite: the old course table (p.21) says MATH 201; the course description (p.38) says MATH 201 and MATH 203. Omar kept the table reading.', 'Old CS bylaw course tables, p.21; course descriptions, p.38', 'Current value: 009 requires MATH 201 (the table reading).'),
  ('old_prereq_conflict_csci_404', 'requisite', 'CSCI 404 prerequisite: the old course table (p.21) says CSCI 313; the course description (p.38) says CSCI 304. Omar kept the table reading.', 'Old CS bylaw course tables, p.21; course descriptions, p.38', 'Current value: 009 requires CSCI 313 (the table reading).'),
  ('old_prereq_conflict_csci_452', 'requisite', 'CSCI 452 prerequisite: the old course table (pp.21-22) says CSCI 451; the course description (p.40) says CSCI 304 and All CORE MATHS. Omar kept the table reading.', 'Old CS bylaw course tables, pp.21-22; course descriptions, p.40', 'Current value: 009 requires CSCI 451 (the table reading).'),
  ('old_prereq_conflict_csci_455', 'requisite', 'CSCI 455 prerequisite: the old course table (pp.21-22) says CSCI 452; the course description (p.40) says CSCI 417 and CSCI 451 and CSCI 452 and All CORE MATHS and PHYS. Omar kept the table reading.', 'Old CS bylaw course tables, pp.21-22; course descriptions, p.40', 'Current value: 009 requires CSCI 452 (the table reading).'),
  ('old_prereq_conflict_csci_456', 'requisite', 'CSCI 456 prerequisite: the old course table (pp.21-22) says CSCI 452; the course description (p.40) says CSCI 451 OR CSCI 452. Omar kept the table reading.', 'Old CS bylaw course tables, pp.21-22; course descriptions, p.40', 'Current value: 009 requires CSCI 452 (the table reading).'),
  ('old_prereq_conflict_csci_457', 'requisite', 'CSCI 457 prerequisite: the old course table (pp.21-22) says CSCI 452; the course description (p.40) says CSCI 456 and CSCI 452 or concurrent. Omar kept the table reading.', 'Old CS bylaw course tables, pp.21-22; course descriptions, p.40', 'Current value: 009 requires CSCI 452 (the table reading).'),
  ('old_prereq_conflict_csci_458', 'requisite', 'CSCI 458 prerequisite: the old course table (pp.21-22) says CSCI 452; the course description (p.40) says CSCI 452 and CSCI 451. Omar kept the table reading.', 'Old CS bylaw course tables, pp.21-22; course descriptions, p.40', 'Current value: 009 requires CSCI 452 (the table reading).'),
  ('old_prereq_conflict_csci_463', 'requisite', 'CSCI 463 prerequisite: the old course table (p.21) says CSCI 207; the course description (p.41) says CSCI 304. Omar kept the table reading.', 'Old CS bylaw course tables, p.21; course descriptions, p.41', 'Current value: 009 requires CSCI 207 (the table reading).'),
  ('old_prereq_conflict_csci_464', 'requisite', 'CSCI 464 prerequisite: the old course table (pp.22-23) says CSCI 304; the course description (p.41) says CSCI 207. Omar kept the table reading.', 'Old CS bylaw course tables, pp.22-23; course descriptions, p.41', 'Current value: 009 requires CSCI 304 (the table reading).'),
  ('old_prereq_conflict_csci_465', 'requisite', 'CSCI 465 prerequisite: the old course table (pp.22-23) says CSCI 419; the course description (p.41) says CSCI 207. Omar kept the table reading.', 'Old CS bylaw course tables, pp.22-23; course descriptions, p.41', 'Current value: 009 requires CSCI 419 (the table reading).'),
  ('old_prereq_conflict_csci_467', 'requisite', 'CSCI 467 prerequisite: the old course table (pp.22-23) says CSCI 322 (general electives, p.22), but MATH 301 and CSCI 322 (Big Data track, p.23); the course description (p.41) says MATH 301 and CSCI 417. The two table listings also disagree; the team chose CSCI 322, as on the track images.', 'Old CS bylaw course tables, pp.22-23; course descriptions, p.41', 'Resolved by team decision (BRIEF.md §6, 2026-11-27): CSCI 322 (track images). Current value: 009 requires CSCI 322 for CSCI 467 (group 1).'),
  ('old_prereq_conflict_csci_475', 'requisite', 'CSCI 475 prerequisite: the old course table (p.22) says CSCI 315; the course description (p.42) says CSCI 207. Omar kept the table reading.', 'Old CS bylaw course tables, p.22; course descriptions, p.42', 'Current value: 009 requires CSCI 315 (the table reading).'),
  ('old_prereq_conflict_phys_101', 'requisite', 'PHYS 101 prerequisite: the old course table (p.19) says Thanaweya Amma or equivalent; the course description (p.36) says MATH 111. Omar kept the table reading, but seed 001 has no old placement row for the certificate, so no row is seeded.', 'Old CS bylaw course tables, p.19; course descriptions, p.36', 'Current value: no requisite row in 009.'),
  ('old_prereq_conflict_csci_205', 'requisite', 'CSCI 205 prerequisite: the old course table (p.20) says CSCI 201; the course description (p.36) says CSCI 201 or concurrent. Omar kept the table reading.', 'Old CS bylaw course tables, p.20; course descriptions, p.36', 'Current value: 009 requires CSCI 201 (the table reading).'),
  ('old_prereq_conflict_csci_221', 'requisite', 'CSCI 221 prerequisite: the old course table (p.20) says PHYS 101 or concurrent; the course description (p.37) says PHYS 101. Omar kept the table reading, but the schema cannot store "or concurrent", so no row is seeded.', 'Old CS bylaw course tables, p.20; course descriptions, p.37', 'Current value: no requisite row in 009.'),
  ('old_prereq_conflict_csci_304', 'requisite', 'CSCI 304 prerequisite: the old course table (p.20) says CSCI 207 and MATH 211 (no connector printed); the course description (p.37) says CSCI 207 and MATH 211 or concurrent. Omar kept the table reading.', 'Old CS bylaw course tables, p.20; course descriptions, p.37', 'Current value: 009 requires CSCI 207 and MATH 211 (the table reading).'),
  ('old_prereq_conflict_csci_451', 'requisite', 'CSCI 451 prerequisite: the old course table (pp.21-22) says CSCI 304; the course description (p.40) says CSCI 304 and All CORE MATHS. Omar kept the table reading.', 'Old CS bylaw course tables, pp.21-22; course descriptions, p.40', 'Current value: 009 requires CSCI 304 (the table reading).'),
  ('old_prereq_conflict_csci_462', 'requisite', 'CSCI 462 prerequisite: the old course table (p.21 and p.23) says CSCI 417; the course description (p.41) says CSCI 417 and All CORE MATHS and PHYS. Omar kept the table reading.', 'Old CS bylaw course tables, p.21 and p.23; course descriptions, p.41', 'Current value: 009 requires CSCI 417 (the table reading).'),
  ('old_prereq_conflict_csci_471', 'requisite', 'CSCI 471 prerequisite: the old course table (p.22) says CSCI 304; the course description (p.42) says CSCI 304 and All CORE MATHS and PHYS. Omar kept the table reading.', 'Old CS bylaw course tables, p.22; course descriptions, p.42', 'Current value: 009 requires CSCI 304 (the table reading).'),
  ('old_prereq_conflict_ecen_101', 'requisite', 'ECEN 101 prerequisite: the old course table (p.20) says PHYS 101; the course description (p.36) says PHYS 101 or concurrent. Omar kept the table reading.', 'Old CS bylaw course tables, p.20; course descriptions, p.36', 'Current value: 009 requires PHYS 101 (the table reading).'),
  ('old_prereq_conflict_csci_459', 'requisite', 'CSCI 459 prerequisite: the old course table (p.22) says CSCI 451; the course description (p.42) has no prerequisite line. Omar kept the table reading.', 'Old CS bylaw course tables, p.22; course descriptions, p.42', 'Current value: 009 requires CSCI 451 (the table reading).'),
  ('old_prereq_conflict_csci_469', 'requisite', 'CSCI 469 prerequisite: the old course table (p.23) says CSCI 461; the course description (p.42) has no prerequisite line. Omar kept the table reading.', 'Old CS bylaw course tables, p.23; course descriptions, p.42', 'Current value: 009 requires CSCI 461 (the table reading).'),
  ('old_prereq_conflict_csci_479', 'requisite', 'CSCI 479 prerequisite: the old course table (p.22) says CSCI 201; the course description (p.42) has no prerequisite line. Omar kept the table reading.', 'Old CS bylaw course tables, p.22; course descriptions, p.42', 'Current value: 009 requires CSCI 201 (the table reading).'),
  ('old_prereq_conflict_csci_490', 'requisite', 'CSCI 490 prerequisite: the old course table (p.21) says Senior Standing; the course description (p.38) has no prerequisite line. The team replaced Senior Standing with a credit minimum.', 'Old CS bylaw course tables, p.21; course descriptions, p.38', 'Resolved by team decision (BRIEF.md §6, 2026-11-27): 67 passed credits, no standing. Current value: 009 has one credits row for CSCI 490 (group 1, minimum 67) and no standing row.'),
  ('old_sheet_only_csci_112', 'course', 'CSCI 112 Intermediate Programming (3 credits) is an old_cs course taken only from the study-plan workbook (Omar''s decision; the 8 codes of old_sheet_only_codes followed). It is not in the old bylaw PDF; all 8 sheets list it, with the same title and credits, as the prerequisite of CSCI 207. The sheet states none of its flags, and its sheet prerequisite is CSCI 102 (all 8 sheets).', 'CS-StudyPlan_Sep 24.xlsx, sheet Science_Intensive_Media, H8:J8 (all 8 sheets agree)', 'Resolved by team decision (Omar, 2026-11-28): workbook codes are official; counts_toward_degree and counts_toward_registration_cap true. Current value: course row true / true / true (counts_in_gpa: team decision (BRIEF.md §6, 2026-11-27)); requisite CSCI 112 -> CSCI 102 from the sheet (K8).'),
  ('old_track_elective_count', 'elective_pool.choose_count', 'The old PDF asks for 6 credit hours of track electives (two 3-credit courses) for the Media and the Big Data track, but every study-plan sheet has one Technical Elective slot (H41), and the term of a second course is not given. Omar''s ruling: keep choose_count 1, the number of courses that one sheet slot takes; adding a second plan slot would invent a semester.', 'Old CS bylaw course tables, p.22 ("Media Informatics Track 6 Credit Hours elective requirements") and p.23 ("Big Data Track 6 Credit Elective requirements")', 'Resolved by team decision (BRIEF.md §6, 2026-11-27): an elective is one box of 3 credits (choose_count 1), and the sheets'' one Technical Elective slot (H41) is kept; no second slot is added (Omar''s ruling). Current value: choose_count 1 on the Media and Big Data pools in 010. The PDF''s 6 credit hours (pp.22-23) remain a source difference.'),
  ('old_math_001_credits', 'course', 'MATH 001 Pre-Calculus Mathematics has 3 credits in the old course table (p.20) but "(O CH)", that is 0 credits, in its course description (p.33). No winner chosen.', 'Old CS bylaw course tables, p.20; course descriptions, p.33', 'Current value: MATH 001 is not seeded.'),
  ('old_csci_322_credits', 'course.credits', 'CSCI 322 Data Analysis has 3 credits in the old course table (p.21) but 4 in its course description (p.38) and in the sample study plan (p.28).', 'Old CS bylaw course tables, p.21; course descriptions, p.38; sample study plan, p.28', 'Current value: 3 credits (the table; keeps the 135-credit total).'),
  ('old_csci_490_credits', 'course.credits', 'CSCI 490 Industrial/Research Training has 2 credits in the old course table (p.21) and the sample study plan (p.28) but 1 in its course description (p.38).', 'Old CS bylaw course tables, p.21; course descriptions, p.38; sample study plan, p.28', 'Current value: 2 credits (the table).'),
  ('old_csci_105_vs_csci_201', 'course', 'The sample study plan (pp.27-28) uses CSCI 105 Introduction to Programming; the course table has CSCI 201 Introduction to Programming (p.20). No source says they are the same course.', 'Old CS bylaw sample study plan, pp.27-28; course tables, p.20', 'Current value: CSCI 201 is seeded; CSCI 105 is not.'),
  ('old_csci_221l_lab', 'course', 'The sample study plan (p.27) splits Logic Design into CSCI 221 (3 credits) and CSCI 221L Logic Design Lab (1 credit), and CSCI 221L has a course description (p.37); the course table has one CSCI 221 Logic Design with 4 credits (p.20).', 'Old CS bylaw sample study plan, p.27; course descriptions, p.37; course tables, p.20', 'Current value: CSCI 221 with 4 credits; CSCI 221L is not seeded.'),
  ('old_math_302_unknown', 'course', 'The Big Data sample study plan (p.29) names MATH 302 as a prerequisite of CSCI 467; MATH 302 is not in the old course tables (pp.19-23).', 'Old CS bylaw sample study plan, p.29', 'Resolved by team decision (Omar, 2026-11-28) on team decision (BRIEF.md §6, 2026-11-27): CSCI 467 requires CSCI 322 alone (track images), so MATH 302 (p.29) is not seeded as a prerequisite of CSCI 467. This is an inference from the CSCI 467 decision; what MATH 302 is remains unknown. Current value: MATH 302 is not seeded; 009 requires CSCI 322 for CSCI 467.'),
  ('old_sheet_only_codes', 'course', 'Eight more codes appear only in the study-plan workbook, not in the old bylaw PDF: CSCI 102, CSCI 208, CSCI 305, ECEN 101C, ENGL 001, MATH 100, PHYS 101C, and SSCI 105 (for SSCI 105 see also project_management_code). ENGL 001 and MATH 100 are on 4 sheets, the others on all 8.', 'CS-StudyPlan_Sep 24.xlsx, sheet Science_Intensive_Media: ENGL 001 B6, MATH 100 B7 ("Math 100"), CSCI 102 B8, ECEN 101C B16, PHYS 101C H6, CSCI 208 H18, CSCI 305 H28, SSCI 105 H42', 'Resolved by team decision (Omar, 2026-11-28): workbook codes are official, the same course as their table twin (CSCI 102 / CSCI 201, CSCI 208 / CSCI 304, CSCI 305 / CSCI 404, ECEN 101C / ECEN 101, PHYS 101C / PHYS 101, SSCI 105 / SSCI 301). Current value: these 8 rows exist as old_cs courses (Omar''s decision, 2026-10-15), code, title, and credits from the cited cell. ENGL 001 and MATH 100: false / false / true (unchanged). The other six: true / true / true (counts_in_gpa: team decision (BRIEF.md §6, 2026-11-27); the other two flags: team decision (Omar, 2026-11-28)). No course_equivalence row and no requisite change: the table codes in prerequisites stay in old_sheet_vs_table_codes.'),
  ('old_or_concurrent', 'requisite', 'The schema has no co-requisite type. "Or concurrent" appears in the old course table for CSCI 221 (p.20) and CSCI 495 (p.21), and in the course descriptions of ECEN 101 and CSCI 205 (p.36), CSCI 304 (p.37), and CSCI 457 (p.40).', 'Old CS bylaw course tables, pp.20-21; course descriptions, pp.36-37 and p.40', 'Current value: no requisite row for CSCI 221; CSCI 495 has only the team''s 100-credit minimum (its "or concurrent" rule is replaced, see old_core_course_count); ECEN 101, CSCI 205, CSCI 304, and CSCI 457 keep the table reading.'),
  ('old_school_certificate_placement', 'requisite', 'Twelve old courses require "Thanaweya Amma or equivalent" (HUMA 101, HUMA 102, HUMA 103, SSCI 101, SSCI 102, SSCI 103, COMM 401, NSCI 102, and PHYS 101 on p.19; MATH 111, CSCI 101, and CSCI 201 on p.20), and ENGL 101 requires "English 101 Placement" (p.19). Seed 001 has no old placement row for either.', 'Old CS bylaw course tables, pp.19-20', 'Current value: no placement requisite for these 13 courses. COMM 401 has a 67-credit minimum (team decision (BRIEF.md §6, 2026-11-27)); the 12 others have no requisite row.'),
  ('old_core_course_count', 'requisite', 'CSCI 495 Senior Project I requires "Completion of 8 core courses Or concurrent" (p.21). The schema has no place for a count of completed courses; the team replaced the rule with a credit minimum.', 'Old CS bylaw course tables, p.21', 'Resolved by team decision (BRIEF.md §6, 2026-11-27): CSCI 495 and CSCI 496 need 100 passed credits. Current value: 009 has a credits row (group 1, minimum 100) for CSCI 495 and for CSCI 496; CSCI 496 also keeps CSCI 495 in group 1 (both apply).'),
  ('new_school_certificate_prereq', 'requisite', 'Ten 2025 courses require "High School certificate or equivalent" (HUMA 103, HUMA 111, HUMA 203, SSCI 101, SSCI 102, SSCI 203, SSCI 204, and SSCI 205 on p.24; CSC 101 and CSC 102 on p.25), and MATH 120 requires "High School certificate (Science Section)" (p.24). Seed 001 has only the high_school_math placement (Math Section).', '2025 bylaw Art. 36, pp.24-25', 'Current value: no requisite row for these 11 courses.'),
  ('new_engl_univ_regulations', 'requisite', 'ENGL 001 and ENGL 002 require "According to Univ. regulations" (p.24); the regulation is not named.', '2025 bylaw Art. 36, p.24', 'Current value: no requisite row for ENGL 001 or ENGL 002.'),
  ('new_csc_493_87_credits', 'requisite', 'CSC 493 Senior Project I requires "Completing 87 Credit Hours or more" (p.28). The database now stores a credits requisite with min_credits_passed 87, independently of the standing bands (27 / 62 / 96). Backend B must evaluate this new type against completed credits at the information cutoff.', '2025 bylaw Art. 36, p.28', 'Current value: 007 seeds one group-1 credits requisite for CSC 493 with minimum 87. Database support is implemented; eligibility-consumer integration must be confirmed before this gap is marked resolved.'),
  ('new_training_project_credits', 'course.credits', 'The p.28 heading says "Industrial/Research Training and Graduation Project (10 credit hours)", but its 4 rows (CSC 291, CSC 391, CSC 493, CSC 494, 3 credits each) add up to 12, and the Article 36 summary table gives Training 6 and Graduation Projects 6 (p.23).', '2025 bylaw Art. 36, p.23 and p.28', 'Current value: 3 credits each (the rows).'),
  ('new_training_project_components', 'course_component', 'The p.28 table gives weekly student workload and number of weeks for CSC 291, CSC 391, CSC 493, and CSC 494, not Lecture, Tutorial, or Lab hours.', '2025 bylaw Art. 36, p.28', 'Current value: no component rows for these 4 courses.'),
  ('old_general_track_elective_pool', 'elective_pool', 'The old general-track elective list (CSCI 451, 452, 455, 456, 457, 458, 461, 462, 464, 465, 467, 471, 472, 475, and 479) asks for 12 credit hours; all 15 have 3 credits, so that is four courses.', 'Old CS bylaw course tables, pp.21-22; elective list, p.30', 'Resolved by team decision (Omar, 2026-11-28): pool "General track elective" (010), track general, choose_count 1, the 15 courses; each of the 4 general plan templates has 4 boxes of it (012), 1 in Year 3 Spring and 3 in Year 4 Spring (open gap old_general_track_big_data_copy).'),
  ('old_general_track_plan_template', 'plan_template, plan_slot', 'The old general track (002) has no study-plan sheet. The team asked for a general plan made of the Media/Big Data sheet boxes up to Year 3 Fall and then 4 general elective boxes (12 credit hours) in place of the track boxes, but the sheets do not fit that. (1) Every Media and Big Data sheet has 3 track boxes, not 4, and none in Year 3 Fall: Media has CSCI 451 (Year 3 Spring: H32 on the Intensive sheets, H30 on the ENGL1 sheets), CSCI 452 (Year 4 Fall: B43 Intensive, B40 ENGL1) and the technical elective (Year 4 Spring, H41); Big Data has CSCI 461 (Year 3 Spring: H32 Intensive, H30 ENGL1), CSCI 467 (Year 4 Spring, H38) and the technical elective (Year 4 Spring, H41). So the 2nd track box is in Year 4 Fall on Media but in Year 4 Spring on Big Data. (2) Math_Intensive_Media and Math_Intensive_Bigdata differ before Year 3 Fall: H5, B16 and B17 hold ECEN 101C, CSCI 207 and CSCI 112 on Media but CSCI 112, ECEN 101C and CSCI 207 on Big Data (the other 3 pairs agree up to Year 3 Fall). (3) In every pair, non-track Year 4 boxes differ between the Media and the Big Data sheet: on the Intensive sheets SSCI 102 is H38 (Year 4 Spring) on Media but B43 (Year 4 Fall) on Big Data; on the ENGL1 sheets CSCI 495 is B42 on Media but B40 on Big Data, SSCI 101 is H43 (Year 4 Spring) on Media but B42 (Year 4 Fall) on Big Data, and Media has NSCI 102 a second time in B43 (old_plan_nsci_102_twice). The bylaw sample plan has a "Year 4 Computer Science - General Track" page (p.28) with 4 track courses (Semester 7: CSCI 471 and CSCI 461; Semester 8: CSCI 451 and CSCI 467), but its other boxes and its earlier years differ from the sheets (for example CSCI 105, CSCI 304, CSCI 404 and SSCI 103, and no CSCI 112).', 'CS-StudyPlan_Sep 24.xlsx, the 8 sheets (track boxes H30, H32, B40, B43, H38 and H41; Math_Intensive_Media and Math_Intensive_Bigdata H5, B16 and B17; Year 4 boxes B40, B42, B43, H38 and H43); Old CS bylaw course tables, pp.21-22; sample study plan, pp.27-28 ("Year 4 Computer Science - General Track", p.28); elective list, p.30', 'Resolved by team decision (Omar, 2026-11-28): (a) 4 general boxes of 3 credits, 1 in CSCI 461''s Year 3 Spring place and 3 in Year 4 Spring (CSCI 467''s place, the technical elective''s place and the next position after the sheet''s last printed box), not 2 + 2 as on p.28, to keep Year 4 Fall within the credit cap; (b) and (c) the 4 general templates copy the Big Data sheet of their english/math pair, Math_Intensive included, with the non-track Year 3 and Year 4 boxes. Copying Big Data rather than Media is a team choice, not a source: open gap old_general_track_big_data_copy. Current value: templates Science_Intensive_General, Science_ENGL1_General, Math_ENGL1_General and Math_Intensive_General (002) with 47, 46, 45 and 46 slots (012).'),
  ('old_general_track_big_data_copy', 'plan_template, plan_slot', 'The 4 general plan templates (Science_Intensive_General, Science_ENGL1_General, Math_ENGL1_General and Math_Intensive_General) copy the Big Data sheet of their english/math pair slot by slot, Years 1-4 and the non-track Year 3 and Year 4 boxes included. The 3 Big Data track boxes, CSCI 461 (Year 3 Spring: H32 on the Intensive sheets, H30 on the ENGL1 sheets), CSCI 467 (Year 4 Spring, H38) and the technical elective (Year 4 Spring, H41), become "General track elective" boxes, and a 4th box is added in Year 4 Spring after the sheet''s last printed box (position 8, after H44, on the Intensive sheets; position 7, after the empty printed box G43, on the ENGL1 sheets). Copying Big Data rather than Media is a team choice, not a source: no sheet and no bylaw page gives a general plan on the workbook''s layout, and the Media and Big Data sheets differ (Math_Intensive H5, B16 and B17 before Year 3 Fall, and the non-track Year 3 Spring and Year 4 boxes in every pair; see old_general_track_plan_template). The placement, 1 box in Year 3 Spring and 3 in Year 4 Spring, departs from the bylaw sample plan, which has 2 general courses in Semester 7 and 2 in Semester 8 (p.28): 2 boxes in Year 4 Fall would make it 23 credits, above the old maximum of 21 (Art. 16). Credits: each general plan has 138 nominal credits, 3 more than the 135 of Art. 18, because the Big Data sheets give the track 9 credits and the general list asks for 12. The "XXXX XXX" gen-ed box of each sheet has no slot (old_gen_ed_elective_pool), so the stored slots total 135, which is what the admin study-plans page shows; the other sheets also have no slot for that box. On the Intensive templates Year 4 Spring has 22 nominal credits (19 stored plus the "XXXX XXX" box H43), above 21; the seeded graduating exception is for summer only. CSCI 495 needs 100 passed credits (009), but every Intensive sheet, Media and Big Data alike and so their 2 general copies, reaches Year 4 Fall with 99 credits (the ENGL1 sheets with 105). On the Intensive sheets and their copies CSCI 305 and its prerequisite CSCI 217 are in the same term (Year 3 Spring, H28 and H30), inherited from the sheet. The 4 general boxes need 4 different courses (one passed course fills one box), and a member fits a box only once its prerequisites are passed (for example CSCI 462 after CSCI 417, which is in Year 4 Fall; CSCI 452 after CSCI 451); several members require codes no sheet uses (CSCI 304, CSCI 201, ECEN 101; old_sheet_vs_table_codes).', 'CS-StudyPlan_Sep 24.xlsx, sheets Science_Intensive_bigdata, Science_ENGL1_Bigdata, Math_ENGL1_Bigdata and Math_Intensive_Bigdata (H28, H30, H32, H38, H41, G43, H43, H44 and the term totals), and the Media sheets for the Intensive Year 1-3 totals; CS Old Bylaws.pdf, Art. 16, p.11; Art. 18, p.12; course tables, pp.21-22; sample study plan, p.28; elective list, p.30; team decision (Omar, 2026-11-28)', 'Current value: the 4 general templates follow the Big Data sheets (002, 012), with the general boxes at Year 3 Spring position 6 (Intensive) or 4 (ENGL1) and Year 4 Spring positions 1, 4 and 8 (Intensive) or 1, 4 and 7 (ENGL1); nothing is moved for the credit totals. CSCI 495 keeps min_credits_passed 100 (009); whether the threshold is 100 or 99 goes to the team. Open until the doctor or registrar gives a general plan, or the team picks another layout.'),
  ('old_gen_ed_elective_pool', 'elective_pool', 'The old general-education elective "NSCI, SSCI, or HUMA" (3 credits) has no course list: the description says "an additional course to be chosen from one of the above three categories".', 'Old CS bylaw course tables, p.19; course descriptions, p.34; sample study plans, pp.28-29 ("XXXX XXX"); CS-StudyPlan_Sep 24.xlsx, "XXXX XXX" slots (H43, H38, or B43)', 'Current value: no pool, so the 8 "XXXX XXX" sheet boxes, and their 4 copies in the general plan templates (old_general_track_big_data_copy), get no plan_slot.'),
  ('new_other_programs_not_seeded', 'course, requisite, elective_pool', 'The 2025 bylaw PDF also has the AI, BMD, and CSEC programs with their own course tables and elective pools (for example pp.38-40, 46-49, and 58-61). Only Article 36 (the CS program) is seeded: courses the other programs share with Article 36 exist, but their other courses and their elective pools are not seeded, and their tables were not read for prerequisites. elective_pool has no program column (the CS and BMD Social Sciences pools differ: BMD selects 4 credit hours, p.47).', '2025 bylaw, pp.38-40, 46-49, 58-61', 'Current value: only the Article 36 courses, requisites, and pools are seeded.')
)
UPDATE data_gap d SET
  description = v.description,
  affected_entity = v.affected_entity,
  source_reference = v.source_reference,
  notes = v.notes,
  updated_at = now()
FROM v
WHERE d.category = v.category;

